head.script:
scwin.onpageload = function () {
    scwin.onresize();

    //전역변수
    scwin.file = "";
    scwin.userId = $p.getParameter("userId");
    scwin.userName = $p.getParameter("userName");
    scwin.profileImageUrl = $p.getParameter("profileImageUrl");
    name_input.setValue(scwin.userName);
    email_input.setValue(scwin.userId);

    if (scwin?.profileImageUrl) {
        profile_button.setStyle("background-image", `url('${scwin.profileImageUrl}')`);
    }
}

scwin.onresize = function (e) {
    // resize 이벤트 정의
    window.onresize = function () {
        scwin.applyResponsiveWidth();
    };

    // 페이지 로딩 시에도 한 번 실행
    scwin.applyResponsiveWidth();
};


//반응형 width 값 조절
scwin.applyResponsiveWidth = function () {
    let width = window.innerWidth;

    if (width <= 700) {
        form_group.setStyle("width", "100%");
    } else if (width <= 1000) {
        form_group.setStyle("width", "60%");
    } else {
        form_group.setStyle("width", "40%");
    }
};


scwin.profile_button_onclick = function (e) {
    $p.$("#fileInput_hidden").click();
    $p.$("#fileInput_hidden").on("change", scwin.fileInput_change);
};

scwin.profileIcon_button_onclick = function (e) {
    $p.$("#fileInput_hidden").click();
    $p.$("#fileInput_hidden").on("change", scwin.fileInput_change);
};

//파일 탐색기에서 이미지 선택했을 때 
scwin.fileInput_change = function (e) {
    const fileInput = $p.$("#fileInput_hidden").get(0);
    const file = fileInput.files[0];

    if (!file) return;
    scwin.file = file;

    const imageUrl = URL.createObjectURL(file);
    profile_button.setStyle("background-image", `url('${imageUrl}')`);
}

//회원정보 수정된거 저장하는 버튼
scwin.update_button_onclick = function (e) {
    let password = password_input.getValue();
    let passwordCheck = passwordCheck_input.getValue();

    let isValid = true;
    let pwRegex = /^(?=.*[A-Za-z])(?=.*\d)(?=.*[!@#$%^&*()_+={}\[\]:;"'<>,.?/-]).{8,}$/;

    // 1. 비밀번호
    if (!password) {
        password_error_text.setValue("*비밀번호를 입력해주세요.");
        isValid = false;
    } else {
        password_error_text.setValue("");
    }

    // 2. 비밀번호 확인
    if (!passwordCheck) {
        passwordCheck_error_text.setValue("*비밀번호 확인을 입력해주세요.");
        isValid = false;
    }
    else {
        passwordCheck_error_text.setValue("");
    }


    if (password && !pwRegex.test(password)) {
        password_error_text.setValue("*비밀번호는 8자 이상이며 영문자·숫자·특수문자를 포함해야 합니다.");
        isValid = false;
    }

    // 비밀번호 일치 검사
    if (password && passwordCheck && password !== passwordCheck) {
        passwordCheck_error_text.setValue("*비밀번호가 일치하지 않습니다.");
        isValid = false;
    }

    if (!isValid) return;

    //  데이터 보내기
    const formData = new FormData();

    // 빈 값으로 필드 세팅
    formData.append("userId", scwin.userId);
    formData.append("userName", name_input.getValue());
    formData.append("password", password_input.getValue());
    formData.append("fileData", scwin.file);

    $.ajax({
        url: "/InsWebApp/user/update.pwkjson",
        type: "POST",
        data: formData,
        processData: false,
        contentType: false,
        success: async function (res) {
            await $c.win.alert("회원정보가 수정되었습니다");
        },
        error: async function (err) {
            await $c.win.alert("회원정보 수정을 실패했습니다");
        }
    });

};
